    input  wire        enc,
    output reg         ready,
    output reg  [31:0] result
);

    // Hàm nhân 2 trong trường GF(2^8)
    function [7:0] xtime;
        input [7:0] b;
        begin
            xtime = (b[7] == 1'b1) ? ((b << 1) ^ 8'h1b) : (b << 1);
        end
    endfunction

    // Các biến trung gian cho 4 byte đầu vào
    wire [7:0] b0, b1, b2, b3;
    assign {b3, b2, b1, b0} = rs1;

    // Tính toán các hệ số nhân cho MixColumns (Encryption)
    // 0x02*b và 0x03*b = (0x02*b ^ b)
    wire [7:0] x2_b0 = xtime(b0), x3_b0 = x2_b0 ^ b0;
    wire [7:0] x2_b1 = xtime(b1), x3_b1 = x2_b1 ^ b1;
    wire [7:0] x2_b2 = xtime(b2), x3_b2 = x2_b2 ^ b2;
    wire [7:0] x2_b3 = xtime(b3), x3_b3 = x2_b3 ^ b3;

    // Tính toán các hệ số nhân cho Inverse MixColumns (Decryption)
    // 0x09 = x8^x1, 0x0b = x8^x2^x1, 0x0d = x8^x4^x1, 0x0e = x8^x4^x2
    wire [7:0] x4_b0 = xtime(x2_b0), x8_b0 = xtime(x4_b0);
    wire [7:0] x4_b1 = xtime(x2_b1), x8_b1 = xtime(x4_b1);
    wire [7:0] x4_b2 = xtime(x2_b2), x8_b2 = xtime(x4_b2);
    wire [7:0] x4_b3 = xtime(x2_b3), x8_b3 = xtime(x4_b3);

    wire [7:0] x9_b0 = x8_b0 ^ b0, xb_b0 = x8_b0 ^ x2_b0 ^ b0, xd_b0 = x8_b0 ^ x4_b0 ^ b0, xe_b0 = x8_b0 ^ x4_b0 ^ x2_b0;
    wire [7:0] x9_b1 = x8_b1 ^ b1, xb_b1 = x8_b1 ^ x2_b1 ^ b1, xd_b1 = x8_b1 ^ x4_b1 ^ b1, xe_b1 = x8_b1 ^ x4_b1 ^ x2_b1;
    wire [7:0] x9_b2 = x8_b2 ^ b2, xb_b2 = x8_b2 ^ x2_b2 ^ b2, xd_b2 = x8_b2 ^ x4_b2 ^ b2, xe_b2 = x8_b2 ^ x4_b2 ^ x2_b2;
    wire [7:0] x9_b3 = x8_b3 ^ b3, xb_b3 = x8_b3 ^ x2_b3 ^ b3, xd_b3 = x8_b3 ^ x4_b3 ^ b3, xe_b3 = x8_b3 ^ x4_b3 ^ x2_b3;

    // Kết quả MixColumns/InvMixColumns tổ hợp
    reg [31:0] mixed_comb;
    always @(*) begin
        if (enc) begin
            // MixColumns chuẩn
            mixed_comb[7:0]   = x2_b0 ^ x3_b1 ^ b2    ^ b3;
            mixed_comb[15:8]  = b0    ^ x2_b1 ^ x3_b2 ^ b3;
            mixed_comb[23:16] = b0    ^ b1    ^ x2_b2 ^ x3_b3;
            mixed_comb[31:24] = x3_b0 ^ b1    ^ b2    ^ x2_b3;
        end else begin
            // Inverse MixColumns chuẩn
            mixed_comb[7:0]   = xe_b0 ^ xb_b1 ^ xd_b2 ^ x9_b3;
            mixed_comb[15:8]  = x9_b0 ^ xe_b1 ^ xb_b2 ^ xd_b3;
            mixed_comb[23:16] = xd_b0 ^ x9_b1 ^ xe_b2 ^ xb_b3;
            mixed_comb[31:24] = xb_b0 ^ xd_b1 ^ x9_b2 ^ xe_b3;
        end
    end

    // Khối điều khiển tuần tự
    always @(posedge clock or posedge reset) begin
        if (reset) begin
            result <= 32'h0;
            ready  <= 1'b0;
        end else if (flush) begin
            result <= flush_data;
            ready  <= 1'b0;
        end else if (valid) begin
            // Kết quả cuối cùng thường XOR với rs2 (AddRoundKey)
            result <= mixed_comb ^ rs2;
            ready  <= 1'b1;
        end else begin
            ready  <= 1'b0;
        end
    end

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):

1.  **Chức năng hệ thống**: Module thực hiện tính toán mã kiểm tra dư tuần hoàn (CRC) 32-bit theo cơ chế "backward" (thường sử dụng đa thức phản chiếu - reflected polynomial 0xEDB88320, phổ biến trong chuẩn Ethernet/IEEE 802.3). Module hỗ trợ hai chế độ: tính toán CRC (`enable`) và dịch dữ liệu (`shift`) để xuất kết quả nối tiếp.

2.  **Phân tích các tín hiệu điều khiển**:
    *   `rst`: Reset bất đồng bộ (Asynchronous Reset), đưa thanh ghi CRC về trạng thái mặc định (thường là `32'hFFFFFFFF`).
    *   `clr`: Xóa đồng bộ (Synchronous Clear), ưu tiên cao hơn các lệnh thực thi để đưa thanh ghi về giá trị khởi tạo.
    *   `shift`: Chế độ dịch. Khi tích cực, thanh ghi hoạt động như một thanh ghi dịch (Shift Register) để đẩy dữ liệu vào từ đầu `data` và đẩy kết quả ra `serial_out`.
    *   `enable`: Chế độ tính toán. Khi tích cực (và `shift` không tích cực), thực hiện cập nhật giá trị CRC dựa trên bit `data` đầu vào.

3.  **Cấu trúc Logic và Triệt tiêu lỗi thiết kế**:
    *   **Tuần tự (Sequential)**: Sử dụng một thanh ghi 32-bit (`crc_reg`). Mọi thay đổi trạng thái đều xảy ra tại cạnh dương `clk`.
    *   **Tránh Inferred Latch**: Sử dụng cấu trúc `if-else if-else` đầy đủ trong khối `always`. Mọi nhánh điều kiện đều gán giá trị cho `crc_reg`.
    *   **Tránh Race Condition**: Sử dụng phép gán non-blocking (`<=`) cho toàn bộ logic cập nhật thanh ghi.
    *   **Dangling Pins**: Tất cả các đầu vào (`data`, `enable`, `shift`, `clr`, `rst`) đều tham gia vào biểu thức logic hoặc điều kiện rẽ nhánh.
    *   **Output**: `crc_out` được gán trực tiếp từ thanh ghi, `serial_out` lấy bit thấp nhất (LSB) của thanh ghi để phục vụ việc truyền nối tiếp.

### Mã Verilog (Hardware RTL):

```verilog
// Standard: IEEE 1364-2001
// Module: adv_dbg_if_cpu1_crc32
// Description: Backward CRC-32 computation with shift and clear capabilities

module adv_dbg_if_cpu1_crc32 (
    input wire clk,
    input wire data,
    input wire enable,
    input wire shift,
    input wire clr,
    input wire rst,
    output wire [31:0] crc_out,
    output wire serial_out
);

    // Register to store the 32-bit CRC value
    reg [31:0] crc_reg;

    // CRC-32 Polynomial (Reflected): 0xEDB88320
    // Standard for IEEE 802.3 and many debug interfaces
    parameter CRC_POLY = 32'hEDB88320;
    parameter CRC_INIT = 32'hFFFFFFFF;

    // Sequential Logic for CRC update and Shift operation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Asynchronous Reset
            crc_reg <= CRC_INIT;
        end
        else if (clr) begin
            // Synchronous Clear
            crc_reg <= CRC_INIT;
        end
        else if (shift) begin
            // Shift Mode: Acts as a standard shift register
            // Data enters from MSB, shifting towards LSB
            crc_reg <= {data, crc_reg[31:1]};
        end
        else if (enable) begin
            // CRC Calculation Mode (Backward/Reflected LFSR)
            // Feedback is XOR of LSB and incoming data
            if (crc_reg[0] ^ data) begin
                crc_reg <= (crc_reg >> 1) ^ CRC_POLY;
            end
            else begin
                crc_reg <= (crc_reg >> 1);
            end
        end
        else begin
            // Default: Maintain state to prevent latches
            crc_reg <= crc_reg;
        end
    end

    // Output Assignments
    // Full 32-bit parallel output
    assign crc_out = crc_reg;

    // Serial output (LSB is shifted out first in backward CRC)
    assign serial_out = crc_reg[0];

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):

1.  **Cấu trúc hệ thống**: Module `fifo_1_ext` được thiết kế theo kiến trúc **Cascade FIFO (FIFO nối tầng)**. Hệ thống bao gồm hai thực thể FIFO (FIFO_1 và FIFO_2) hoạt động phối hợp:
    *   **FIFO_1**: Nhận dữ liệu trực tiếp từ `data_in` khi `w_en` tích cực.
    *   **FIFO_2**: Nhận dữ liệu từ đầu ra của FIFO_1 (`data_out_1`) và cung cấp dữ liệu cuối cùng ra `final_data` khi `r_en` tích cực.
    *   **Cơ chế chuyển tiếp (Internal Transfer)**: Dữ liệu tự động chuyển từ FIFO_1 sang FIFO_2 khi FIFO_1 không trống (`!empty_1`) và FIFO_2 chưa đầy (`!full_2`).

2.  **Quản lý tài nguyên và Trạng thái**:
    *   **Độ rộng/Độ sâu**: Mỗi FIFO sử dụng bộ đếm 4-bit (`fifo_cnt_1`, `fifo_cnt_2`), tương ứng với độ sâu tối đa là 15 phần tử (để tránh nhập nhằng giữa Full/Empty khi dùng con trỏ).
    *   **Tín hiệu Full/Empty**: 
        *   `full` (Global): Tích cực khi FIFO_1 đầy (không thể nhận thêm dữ liệu từ bên ngoài).
        *   `empty` (Global): Tích cực khi FIFO_2 trống (không còn dữ liệu để xuất ra ngoài).

3.  **Xử lý Race Condition và Latch**:
    *   Sử dụng xung clock duy nhất (`clk`) và reset đồng bộ (`rst`) để đảm bảo tính ổn định toàn cục.
    *   Toàn bộ logic cập nhật con trỏ (`wr_ptr`, `rd_ptr`) và bộ đếm (`cnt`) sử dụng phép gán **non-blocking (`<=`)** trong khối `always @(posedge clk)`.
    *   Triệt tiêu **Inferred Latch**: Mọi trạng thái của bộ đếm và con trỏ đều được khởi tạo tại nhánh `if (rst)` và có điều kiện `else` bao quát mọi trường hợp.

4.  **Giao tiếp I/O**:
    *   `data_out_1` đóng vai trò là điểm kiểm tra trung gian (intermediate probe) giữa hai tầng FIFO.
    *   `fifo_cnt_1` và `fifo_cnt_2` cung cấp thông tin giám sát dung lượng thời gian thực cho từng tầng.

### Thiết kế vi mạch (RTL Code):

```verilog
module fifo_1_ext (
    input [7:0] data_in,
    input clk,
    input rst,
    input w_en,
    input r_en,
    output [7:0] final_data,
    output full,
    output empty,
    output [7:0] data_out_1,
    output reg [3:0] fifo_cnt_1,
    output reg [3:0] fifo_cnt_2
);

    // Tham số cấu hình FIFO (Depth = 15 để phù hợp counter 4-bit)
    integer i;
    reg [7:0] mem1 [0:14];
    reg [7:0] mem2 [0:14];

    reg [3:0] wr_ptr1, rd_ptr1;
    reg [3:0] wr_ptr2, rd_ptr2;

    // Tín hiệu điều khiển nội bộ
    wire internal_transfer;
    wire full_1, empty_1;
    wire full_2, empty_2;

    // Logic xác định trạng thái từng FIFO
    assign full_1  = (fifo_cnt_1 == 4'd15);
    assign empty_1 = (fifo_cnt_1 == 4'd0);
    assign full_2  = (fifo_cnt_2 == 4'd15);
    assign empty_2 = (fifo_cnt_2 == 4'd0);

    // Cơ chế chuyển tiếp tự động giữa 2 tầng FIFO
    assign internal_transfer = (!empty_1 && !full_2);

    // Gán đầu ra trạng thái hệ thống
    assign full  = full_1;
    assign empty = empty_2;
    assign data_out_1 = mem1[rd_ptr1];
    assign final_data = mem2[rd_ptr2];

    // Điều khiển FIFO tầng 1
    always @(posedge clk) begin
        if (rst) begin
            wr_ptr1 <= 4'd0;
            rd_ptr1 <= 4'd0;
            fifo_cnt_1 <= 4'd0;
            for (i = 0; i < 15; i = i + 1) mem1[i] <= 8'd0;
        end else begin
            case ({w_en && !full_1, internal_transfer})
                2'b10: begin // Chỉ ghi vào FIFO 1
                    mem1[wr_ptr1] <= data_in;
                    wr_ptr1 <= (wr_ptr1 == 4'd14) ? 4'd0 : wr_ptr1 + 4'd1;
                    fifo_cnt_1 <= fifo_cnt_1 + 4'd1;
                end
                2'b01: begin // Chỉ đọc từ FIFO 1 (chuyển sang FIFO 2)
                    rd_ptr1 <= (rd_ptr1 == 4'd14) ? 4'd0 : rd_ptr1 + 4'd1;
                    fifo_cnt_1 <= fifo_cnt_1 - 4'd1;
                end
                2'b11: begin // Vừa ghi vừa đọc FIFO 1
                    mem1[wr_ptr1] <= data_in;
                    wr_ptr1 <= (wr_ptr1 == 4'd14) ? 4'd0 : wr_ptr1 + 4'd1;
                    rd_ptr1 <= (rd_ptr1 == 4'd14) ? 4'd0 : rd_ptr1 + 4'd1;
                    // fifo_cnt_1 giữ nguyên
                end
                default: ; // Không hoạt động
            endcase
        end
    end

    // Điều khiển FIFO tầng 2
    always @(posedge clk) begin
        if (rst) begin
            wr_ptr2 <= 4'd0;
            rd_ptr2 <= 4'd0;
            fifo_cnt_2 <= 4'd0;
            for (i = 0; i < 15; i = i + 1) mem2[i] <= 8'd0;
        end else begin
            case ({internal_transfer, r_en && !empty_2})
                2'b10: begin // Chỉ ghi vào FIFO 2 (nhận từ FIFO 1)
                    mem2[wr_ptr2] <= data_out_1;
                    wr_ptr2 <= (wr_ptr2 == 4'd14) ? 4'd0 : wr_ptr2 + 4'd1;
                    fifo_cnt_2 <= fifo_cnt_2 + 4'd1;
                end
                2'b01: begin // Chỉ đọc từ FIFO 2 ra ngoài
                    rd_ptr2 <= (rd_ptr2 == 4'd14) ? 4'd0 : rd_ptr2 + 4'd1;
                    fifo_cnt_2 <= fifo_cnt_2 - 4'd1;
                end
                2'b11: begin // Vừa ghi vừa đọc FIFO 2
                    mem2[wr_ptr2] <= data_out_1;
                    wr_ptr2 <= (wr_ptr2 == 4'd14) ? 4'd0 : wr_ptr2 + 4'd1;
                    rd_ptr2 <= (rd_ptr2 == 4'd14) ? 4'd0 : rd_ptr2 + 4'd1;
                    // fifo_cnt_2 giữ nguyên
                end
                default: ; // Không hoạt động
            endcase
        end
    end

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):

1.  **Phân tích I/O và Chức năng:**
    *   **Đầu vào:** `clk` (xung nhịp gốc), `rst` (reset bất đồng bộ, tích cực cao).
    *   **Đầu ra:** 4 tín hiệu xung nhịp `clk_0`, `clk_90`, `clk_180`, `clk_270`. Các tín hiệu này có cùng tần số (bằng 1/4 tần số `clk` đầu vào) nhưng lệch pha nhau 90 độ tương ứng.
2.  **Cấu trúc logic:**
    *   Sử dụng một bộ đếm 2-bit (`count[1:0]`) để chia tần số. Bộ đếm này sẽ lặp lại chu kỳ 4 trạng thái: `00 -> 01 -> 10 -> 11`.
    *   Mỗi trạng thái của bộ đếm tương ứng với một góc pha 90 độ của chu kỳ đầu ra ($360^\circ / 4 = 90^\circ$).
    *   **Giải mã pha (Phase Decoding):** Để đảm bảo duty cycle là 50% cho các xung đầu ra:
        *   `clk_0` (0°): Tích cực khi `count` ở trạng thái 0 và 1.
        *   `clk_90` (90°): Tích cực khi `count` ở trạng thái 1 và 2.
        *   `clk_180` (180°): Tích cực khi `count` ở trạng thái 2 và 3.
        *   `clk_270` (270°): Tích cực khi `count` ở trạng thái 3 và 0.
3.  **Xử lý lỗi thiết kế:**
    *   **Inferred Latch:** Sử dụng phép gán liên tục (`assign`) cho các đầu ra dựa trên giá trị của bộ đếm, đảm bảo logic tổ hợp thuần túy không tạo chốt ẩn.
    *   **Race Condition:** Bộ đếm sử dụng phép gán non-blocking (`<=`) trong khối `always @(posedge clk or posedge rst)` để triệt tiêu xung nhiễu và đảm bảo tính ổn định của máy trạng thái.
    *   **Dangling Pins:** Tất cả các bit của bộ đếm `count` đều được sử dụng trong logic giải mã đầu ra.

### Thiết kế chi tiết (Verilog RTL):

```verilog
// IEEE 1364-2001 Verilog Standard
// Module: clk_ps
// Function: 4-Phase Shifted Clock Generator (0, 90, 180, 270 degrees)

module clk_ps (
    input wire rst,
    input wire clk,
    output wire clk_0,
    output wire clk_90,
    output wire clk_180,
    output wire clk_270
);

    // Bo dem 2-bit de chia tan so va tao cac phan vung pha
    reg [1:0] count;

    // Khoi logic tuan tu: Bo dem tang vao moi canh len clk
    // Reset bat dong bo (Asynchronous Reset)
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 2'b00;
        end else begin
            count <= count + 1'b1;
        end
    end

    // Giai ma to hop de tao ra 4 pha voi Duty Cycle 50%
    // clk_0:   High tai count 0, 1 (Tuong ung pha 0 do)
    // clk_90:  High tai count 1, 2 (Tre 1 chu ky clk = 90 do)
    // clk_180: High tai count 2, 3 (Tre 2 chu ky clk = 180 do)
    // clk_270: High tai count 3, 0 (Tre 3 chu ky clk = 270 do)

    assign clk_0   = (count == 2'b00 || count == 2'b01);
    assign clk_90  = (count == 2'b01 || count == 2'b10);
    assign clk_180 = (count == 2'b10 || count == 2'b11);
    assign clk_270 = (count == 2'b11 || count == 2'b00);

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):

1.  **Chức năng cốt lõi**: Module là một bộ chốt dữ liệu loại D (D-Flip-Flop) cơ bản, thực hiện việc lấy mẫu tín hiệu đầu vào `D` tại cạnh dương của xung nhịp `CLK`. Đặc điểm quan trọng là cung cấp đồng thời hai đầu ra: đầu ra chính `Q` và đầu ra đảo `Q_N`.
2.  **Phân tích I/O và Độ rộng bit**:
    *   `CLK` (1-bit): Tín hiệu kích hoạt (trigger) cho quá trình chuyển trạng thái.
    *   `D` (1-bit): Dữ liệu đầu vào cần được lưu trữ.
    *   `Q` (1-bit): Trạng thái hiện tại của Flip-Flop.
    *   `Q_N` (1-bit): Trạng thái bù (complementary) của `Q`.
3.  **Cấu trúc Logic**:
    *   **Tuần tự (Sequential)**: Sử dụng khối `always @(posedge CLK)` để cập nhật giá trị từ `D` vào một thanh ghi nội bộ (`q_reg`).
    *   **Tổ hợp (Combinational)**: Đầu ra `Q` được nối trực tiếp từ thanh ghi, trong khi `Q_N` được tính toán bằng phép toán NOT logic (`~`) từ giá trị của thanh ghi đó.
4.  **Xử lý lỗi thiết kế**:
    *   **Inferred Latch**: Triệt tiêu hoàn toàn bằng cách sử dụng cấu trúc tuần tự kích hoạt theo cạnh (edge-triggered), không có điều kiện `if` thiếu nhánh `else` trong khối tổ hợp.
    *   **Race Condition**: Sử dụng phép gán non-blocking (`<=`) trong khối `always` để đảm bảo dữ liệu được dịch chuyển đúng theo mô hình mô phỏng sự kiện (event-driven simulation).
    *   **Dangling Pins**: Tất cả các cổng đầu vào (`CLK`, `D`) đều được sử dụng để điều khiển logic chuyển mạch; tất cả đầu ra (`Q`, `Q_N`) đều được gán giá trị xác định.

### Verilog Code:

```verilog
// Standard: IEEE 1364-2001
// Module: sky130_fd_sc_hd__dfxbp_2
// Description: D-Flip-Flop with complementary outputs (Q and Q_N)

module sky130_fd_sc_hd__dfxbp_2 (
    input CLK,
    input D,
    output Q,
    output Q_N
);

    // Thanh ghi noi bo de luu tru trang thai cua Flip-Flop
    reg q_internal;

    // Khoi logic tuan tu: Cap nhat tai canh duong cua xung nhip
    // Su dung phep gan non-blocking (<=) de tranh Race Condition
    always @(posedge CLK) begin
        q_internal <= D;
    end

    // Gan gia tri cho cac dau ra
    // Q la gia tri hien tai cua thanh ghi
    // Q_N la gia tri dao (complementary) cua thanh ghi
    assign Q   = q_internal;
    assign Q_N = ~q_internal;

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):

1.  **Chức năng cốt lõi**: Module thực hiện chuyển đổi không gian màu từ RGB (8-bit mỗi kênh) sang YUV (YCbCr) theo chuẩn SDTV (BT.601). Công thức toán học được sử dụng là dạng số nguyên cố định (fixed-point) để tối ưu hóa tài nguyên phần cứng:
    *   $Y = (77R + 150G + 29B) >> 8$
    *   $U = (-43R - 84G + 127B + 32768) >> 8$
    *   $V = (127R - 106G - 21B + 32768) >> 8$
    *   *Lưu ý*: Giá trị 32768 tương ứng với offset 128 trong miền 8-bit ($128 \times 2^8$).

2.  **Chiến lược thiết kế Pipeline**: Để đảm bảo timing closure ở tần số cao và tránh Race Condition, kiến trúc được chia làm 3 tầng pipeline:
    *   **Tầng 1 (Multiplication)**: Tính toán các tích số ($77 \times R, 150 \times G, \dots$).
    *   **Tầng 2 (Summation)**: Cộng/trừ các tích số và cộng offset.
    *   **Tầng 3 (Output)**: Thực hiện phép dịch bit (shift right) và gán kết quả vào thanh ghi đầu ra.

3.  **Đồng bộ hóa tín hiệu điều khiển**: Các tín hiệu `in_href` và `in_vsync` được đẩy qua các thanh ghi trễ (Shift Register) có độ sâu bằng đúng số tầng pipeline của dữ liệu (3 chu kỳ clock). Điều này đảm bảo dữ liệu YUV đầu ra khớp chính xác với khung hình của tín hiệu đồng bộ.

4.  **Xử lý lỗi thiết kế**:
    *   **Inferred Latch**: Sử dụng reset hệ thống (`rst_n`) cho tất cả thanh ghi. Mọi đường dẫn dữ liệu đều nằm trong khối `always @(posedge pclk)`.
    *   **Dangling Pins**: Tất cả các bit của kết quả trung gian đều được sử dụng hoặc được cắt tỉa logic (truncation) một cách có chủ đích thông qua phép dịch bit.
    *   **Overflow**: Các thanh ghi trung gian được tính toán độ rộng bit đủ lớn (16-18 bit) để chứa giá trị cực đại trước khi dịch bit.

### Verilog RTL Code:

```verilog
// Standard: IEEE 1364-2001
// Module: isp_csc
// Function: RGB888 to YUV444 Conversion with 3-stage Pipeline

module isp_csc (
    input  wire       pclk,
    input  wire       rst_n,
    input  wire       in_href,
    input  wire       in_vsync,
    input  wire [7:0] in_r,
    input  wire [7:0] in_g,
    input  wire [7:0] in_b,
    output reg        out_href,
    output reg        out_vsync,
    output reg  [7:0] out_y,
    output reg  [7:0] out_u,
    output reg  [7:0] out_v
);

    // Stage 1: Multiplication Registers
    reg [15:0] mult_r_y, mult_g_y, mult_b_y;
    reg [15:0] mult_r_u, mult_g_u, mult_b_u;
    reg [15:0] mult_r_v, mult_g_v, mult_b_v;

    // Stage 2: Summation Registers
    reg [16:0] sum_y;
    reg [16:0] sum_u;
    reg [16:0] sum_v;

    // Control Signal Pipeline (3 cycles delay)
    reg [2:0] href_d;
    reg [2:0] vsync_d;

    // --- Pipeline Stage 1: Multiplications ---
    always @(posedge pclk or negedge rst_n) begin
        if (!rst_n) begin
            mult_r_y <= 16'd0; mult_g_y <= 16'd0; mult_b_y <= 16'd0;
            mult_r_u <= 16'd0; mult_g_u <= 16'd0; mult_b_u <= 16'd0;
            mult_r_v <= 16'd0; mult_g_v <= 16'd0; mult_b_v <= 16'd0;
        end else begin
            // Y = 0.299R + 0.587G + 0.114B (Scaled by 256)
            mult_r_y <= in_r * 8'd77;
            mult_g_y <= in_g * 8'd150;
            mult_b_y <= in_b * 8'd29;
            // U = -0.169R - 0.331G + 0.500B + 128
            mult_r_u <= in_r * 8'd43;
            mult_g_u <= in_g * 8'd84;
            mult_b_u <= in_b * 8'd127;
            // V = 0.500R - 0.419G - 0.081B + 128
            mult_r_v <= in_r * 8'd127;
            mult_g_v <= in_g * 8'd106;
            mult_b_v <= in_b * 8'd21;
        end
    end

    // --- Pipeline Stage 2: Summation ---
    always @(posedge pclk or negedge rst_n) begin
        if (!rst_n) begin
            sum_y <= 17'd0;
            sum_u <= 17'd0;
            sum_v <= 17'd0;
        end else begin
            sum_y <= mult_r_y + mult_g_y + mult_b_y;
            sum_u <= mult_b_u - mult_r_u - mult_g_u + 17'd32768;
            sum_v <= mult_r_v - mult_g_v - mult_b_v + 17'd32768;
        end
    end

    // --- Pipeline Stage 3: Output Assignment (Shift Right) ---
    always @(posedge pclk or negedge rst_n) begin
        if (!rst_n) begin
            out_y <= 8'd0;
            out_u <= 8'd0;
            out_v <= 8'd0;
        end else begin
            out_y <= sum_y[15:8];
            out_u <= sum_u[15:8];
            out_v <= sum_v[15:8];
        end
    end

    // --- Control Signal Delay Line ---
    always @(posedge pclk or negedge rst_n) begin
        if (!rst_n) begin
            href_d  <= 3'b000;
            vsync_d <= 3'b000;
            out_href  <= 1'b0;
            out_vsync <= 1'b0;
        end else begin
            href_d  <= {href_d[1:0], in_href};
            vsync_d <= {vsync_d[1:0], in_vsync};
            out_href  <= href_d[2];
            out_vsync <= vsync_d[2];
        end
    end

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):

1.  **Chức năng hệ thống**: Module `or1200_sb_fifo` đóng vai trò là một bộ đệm hàng đợi (FIFO) đồng bộ quy mô nhỏ, thường dùng trong Store Buffer của kiến trúc OpenRISC. Nó quản lý việc lưu trữ dữ liệu 2-bit, điều phối luồng dữ liệu giữa các giai đoạn xử lý khác nhau thông qua các tín hiệu điều khiển ghi (`wr_i`) và đọc (`rd_i`).

2.  **Cấu trúc lưu trữ và Con trỏ**:
    *   **Bộ nhớ nội**: Sử dụng một mảng thanh ghi (Register Array) thay vì RAM khối để tối ưu tốc độ truy cập trong 1 chu kỳ. Với đặc thù Store Buffer, độ sâu (depth) thường được thiết kế là 4 để cân bằng giữa tài nguyên và hiệu năng.
    *   **Con trỏ (Pointers)**: `wr_ptr` (con trỏ ghi) và `rd_ptr` (con trỏ đọc) có độ rộng 2-bit để định vị 4 ô nhớ.
    *   **Bộ đếm (Counter)**: `cnt` (3-bit) theo dõi số lượng phần tử hiện có (từ 0 đến 4) để xác định trạng thái `full_o` và `empty_o`.

3.  **Xử lý Logic và Triệt tiêu lỗi**:
    *   **Race Condition**: Toàn bộ logic cập nhật con trỏ, bộ đếm và dữ liệu được đặt trong khối `always @(posedge clk_i)` sử dụng phép gán non-blocking (`<=`), đảm bảo tính ổn định của dữ liệu tại biên xung clock.
    *   **Inferred Latch**: Trạng thái `full_o` và `empty_o` được tính toán bằng logic tổ hợp từ bộ đếm `cnt`, đảm bảo luôn có giá trị xác định.
    *   **Dangling Pins**: Tất cả các bit của `dat_i` và các tín hiệu điều khiển đều được tham chiếu trong logic cập nhật trạng thái.
    *   **Cơ chế bảo vệ**: Dữ liệu chỉ được ghi khi `wr_i` tích cực và FIFO chưa đầy; dữ liệu chỉ được đọc khi `rd_i` tích cực và FIFO không trống.

### Thiết kế Verilog (RTL Distillation):

```verilog
module or1200_sb_fifo (
    // Clock and Reset
    input             clk_i,
    input             rst_i,
    // Data Interface
    input      [1:0]  dat_i,
    input             wr_i,
    input             rd_i,
    output     [1:0]  dat_o,
    // Status Interface
    output            full_o,
    output            empty_o
);

    // Internal Parameters
    parameter ADDR_WIDTH = 2;
    parameter DEPTH      = 4; // 2^ADDR_WIDTH

    // Internal Registers
    reg [1:0]        mem [0:DEPTH-1];
    reg [ADDR_WIDTH-1:0] wr_ptr;
    reg [ADDR_WIDTH-1:0] rd_ptr;
    reg [ADDR_WIDTH:0]   cnt;

    // Continuous Assignment for Status Flags
    assign empty_o = (cnt == {{(ADDR_WIDTH){1'b0}}, 1'b0});
    assign full_o  = (cnt == DEPTH[ADDR_WIDTH:0]);

    // Data Output Assignment (Read logic)
    assign dat_o   = mem[rd_ptr];

    // Synchronous Logic for Pointers, Counter and Memory
    always @(posedge clk_i) begin
        if (rst_i) begin
            wr_ptr <= 2'b00;
            rd_ptr <= 2'b00;
            cnt    <= 3'b000;
        end
        else begin
            // Case 1: Simultaneous Read and Write
            if (wr_i && !full_o && rd_i && !empty_o) begin
                mem[wr_ptr] <= dat_i;
                wr_ptr      <= wr_ptr + 1'b1;
                rd_ptr      <= rd_ptr + 1'b1;
                // cnt remains unchanged
            end
            // Case 2: Write Only
            else if (wr_i && !full_o) begin
                mem[wr_ptr] <= dat_i;
                wr_ptr      <= wr_ptr + 1'b1;
                cnt         <= cnt + 1'b1;
            end
            // Case 3: Read Only
            else if (rd_i && !empty_o) begin
                rd_ptr      <= rd_ptr + 1'b1;
                cnt         <= cnt - 1'b1;
            end
            // Case 4: Idle - No change
            else begin
                wr_ptr <= wr_ptr;
                rd_ptr <= rd_ptr;
                cnt    <= cnt;
            end
        end
    end

endmodule
```

### Phân tích kiến trúc vi mạch (Teacher CoT):

1.  **Chức năng hệ thống**:
    *   Module thực hiện chia tần số clock cấu hình được (`i_divisor`).
    *   Đặc điểm đặc biệt: Khi tín hiệu `i_rst` ở trạng thái tích cực (active), mạch thực hiện đếm và chia clock. Khi `i_rst` không tích cực, mạch cho phép clock đầu vào `i_clk` đi thẳng ra đầu ra `o_clk` (bypass mode).
    *   Cơ chế chia clock chẵn (Even Divider): Để tạo ra clock có duty cycle 50%, mạch sẽ đảo trạng thái (toggle) đầu ra sau mỗi nửa chu kỳ đếm ($i\_divisor / 2$).

2.  **Phân tích I/O và Độ rộng bit**:
    *   `i_clk`, `i_rst`: Tín hiệu điều khiển 1-bit.
    *   `i_divisor [15:0]`: Bộ chia 16-bit, cho phép chia tối đa $2^{16}$.
    *   `o_clk`: Tín hiệu clock đầu ra sau khi xử lý.

3.  **Cấu trúc logic và Xử lý tín hiệu**:
    *   **Phần tuần tự (Sequential)**: Sử dụng một thanh ghi đếm `r_cnt` (16-bit) và một thanh ghi trạng thái clock `r_clk_div`.
    *   **Điều kiện Toggle**: Khi `r_cnt` đạt giá trị $(i\_divisor >> 1) - 1$, thanh ghi `r_clk_div` sẽ đảo bit và `r_cnt` quay về 0.
    *   **Triệt tiêu Latch và Race Condition**: 
        *   Sử dụng phép gán non-blocking (`<=`) trong khối `always @(posedge i_clk)` để đảm bảo tính ổn định của Flip-Flop.
        *   Sử dụng khối tổ hợp `assign` với toán tử điều kiện để chọn nguồn clock đầu ra, đảm bảo không có chốt ẩn (Inferred Latch) và không có chân lơ lửng.
        *   Toàn bộ logic đếm chỉ hoạt động khi `i_rst` tích cực (theo đặc tả), nếu không sẽ reset bộ đếm về 0 để tránh trạng thái không xác định.

4.  **RTL Distillation**:
    *   `r_cnt`: Bộ đếm chu kỳ.
    *   `r_clk_div`: Thanh ghi tạo xung clock chia.
    *   `o_clk`: Mux chọn giữa `r_clk_div` (khi `i_rst` đúng) và `i_clk` (khi `i_rst` sai).

### Mã Verilog (Hardware RTL):

```verilog
// Standard: IEEE 1364-2001
// Module: down_clocking_even
// Description: Configurable clock divider with bypass mode based on reset state.

module down_clocking_even (
    input  wire        i_clk,      // Input clock
    input  wire        i_rst,      // Control/Reset signal
    input  wire [15:0] i_divisor,  // 16-bit divisor value
    output wire        o_clk       // Output clock
);

    // Internal registers for counting and clock generation
    reg [15:0] r_cnt;
    reg        r_clk_div;

    // Half divisor calculation for even clock toggling
    // Using wire for clarity in synthesis
    wire [15:0] w_half_divisor;
    assign w_half_divisor = i_divisor >> 1;

    // Sequential logic for clock division
    // The counter runs only when i_rst is active (as per specification)
    always @(posedge i_clk) begin
        if (i_rst) begin
            // Check if counter reached (divisor/2 - 1)
            // Note: If i_divisor is 0 or 1, behavior is handled by bypass logic
            if (w_half_divisor > 16'd0 && r_cnt >= (w_half_divisor - 16'd1)) begin
                r_cnt     <= 16'd0;
                r_clk_div <= ~r_clk_div;
            end else begin
                r_cnt     <= r_cnt + 16'd1;
                r_clk_div <= r_clk_div;
            end
        end else begin
            // Reset internal states when i_rst is not active
            r_cnt     <= 16'd0;
            r_clk_div <= 1'b0;
        end
    end

    // Output logic: Pass through i_clk if i_rst is not active, 
    // otherwise output the divided clock.
    // This implements the "passing through the input clock if not [reset active]" logic.
    assign o_clk = (i_rst) ? r_clk_div : i_clk;

endmodule
```

