```verilog
module smart_home_security (
    input  wire       clk,
    input  wire       rst,
    input  wire       motion_pir,
    input  wire       smoke_gas,
    input  wire       arm_mode,
    output reg        siren,
    output reg        sprinkler,
    output reg  [1:0] status_code
);
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            siren       <= 1'b0;
            sprinkler   <= 1'b0;
            status_code <= 2'b00;
        end else begin
            if (smoke_gas) begin
                siren       <= 1'b1;
                sprinkler   <= 1'b1;
                status_code <= 2'b10;
            end else if (arm_mode && motion_pir) begin
                siren       <= 1'b1;
                sprinkler   <= 1'b0;
                status_code <= 2'b01;
            end else begin
                siren       <= 1'b0;
                sprinkler   <= 1'b0;
                status_code <= 2'b00;
            end
        end
    end
endmodule
```

