    input  wire       clk,
    input  wire       rst,
    input  wire [2:0] call_btn, // {Floor 3, 2, 1}
    input  wire [2:0] floor_sensor,
    output reg  [1:0] motor_dir, // 00: Stop, 01: Up, 10: Down
