module spi_master_mode0 (
    input  wire       clk,
    input  wire       rst,
    input  wire       start,
    input  wire [7:0] tx_data,
    output reg  [7:0] rx_data,
    output reg        sclk,
    output reg        cs_n,
    output reg        mosi,
    input  wire       miso,
    output reg        busy
);
    localparam IDLE = 2'b00, SCLK_LOW = 2'b01, SCLK_HIGH = 2'b10, DONE = 2'b11;
    reg [1:0] state;
    reg [2:0] bit_cnt;
    reg [7:0] shift_tx, shift_rx;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state    <= IDLE;
            sclk     <= 1'b0;
            cs_n     <= 1'b1;
            mosi     <= 1'b0;
            busy     <= 1'b0;
            rx_data  <= 8'd0;
            bit_cnt  <= 3'd7;
            shift_tx <= 8'd0;
            shift_rx <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    sclk <= 1'b0;
                    cs_n <= 1'b1;
                    busy <= 1'b0;
                    if (start) begin
                        state    <= SCLK_LOW;
                        cs_n     <= 1'b0;
                        busy     <= 1'b1;
                        shift_tx <= tx_data;
                        bit_cnt  <= 3'd7;
                    end
                end
                SCLK_LOW: begin
                    sclk <= 1'b0;
                    mosi <= shift_tx[bit_cnt];
                    state <= SCLK_HIGH;
