                SCLK_HIGH: begin
                    sclk <= 1'b1;
                    shift_rx[bit_cnt] <= miso;
                    if (bit_cnt == 3'd0) begin
                        state <= DONE;
                    end else begin
                        bit_cnt <= bit_cnt - 1'b1;
                        state   <= SCLK_LOW;
