	output out_xnor,
	output out_anotb
);

	// AND gate
	assign out_and = a & b;

	// OR gate
	assign out_or = a | b;

	// XOR gate
	assign out_xor = a ^ b;

	// NAND gate
	assign out_nand = ~(a & b);

	// NOR gate
	assign out_nor = ~(a | b);

	// XNOR gate
	assign out_xnor = ~(a ^ b);

	// AND-NOT gate (a AND NOT b)
	assign out_anotb = a & ~b;

endmodule
